// Uses JPA annotations ONLY — no Hibernate-specific imports → portable!
package com.bank.ipo.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

@Entity
@Table(name = "ipo_subscriptions")
public class IpoSubscription {

    @Id
    @Column(name = "subscription_id")
    private String subscriptionId;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(name = "company_name", nullable = false)
    private String companyName;

    @Column(name = "lot_size", nullable = false)
    private int lotSize;

    @Column(name = "lots_applied", nullable = false)
    private int lotsApplied;

    @Column(name = "price_per_share", nullable = false)
    private BigDecimal pricePerShare;

    @Column(name = "total_amount", nullable = false)
    private BigDecimal totalAmount;

    @Column(nullable = false)
    private String status;

    @Column(name = "allotment_date")
    private LocalDate allotmentDate;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected IpoSubscription() {}

    public IpoSubscription(String subscriptionId, String accountId, String companyName,
                            int lotSize, int lotsApplied, BigDecimal pricePerShare) {
        this.subscriptionId = subscriptionId;
        this.accountId = accountId;
        this.companyName = companyName;
        this.lotSize = lotSize;
        this.lotsApplied = lotsApplied;
        this.pricePerShare = pricePerShare;
        this.totalAmount = pricePerShare.multiply(BigDecimal.valueOf(lotSize * lotsApplied));
        this.status = "APPLIED";
        this.createdAt = LocalDateTime.now();
    }

    public void allot(LocalDate date) { this.status = "ALLOTTED"; this.allotmentDate = date; }
    public void reject() { this.status = "REJECTED"; }

    public String getSubscriptionId() { return subscriptionId; }
    public String getAccountId() { return accountId; }
    public String getCompanyName() { return companyName; }
    public BigDecimal getTotalAmount() { return totalAmount; }
    public String getStatus() { return status; }
}
