import org.springframework.data.jpa.repository.JpaRepository;
import java.util.List;

public interface IpoRepository extends JpaRepository<IpoSubscription, String> {
    List<IpoSubscription> findByAccountIdAndStatus(String accountId, String status);
    // Spring generates: em.createQuery("SELECT i FROM IpoSubscription i WHERE i.accountId = ?1 AND i.status = ?2")
    // Hibernate translates JPQL → PostgreSQL SQL using PostgreSQLDialect
}
