package com.bank.ipo.service;

import com.bank.ipo.dto.*;
import com.bank.ipo.model.IpoSubscription;
import com.bank.ipo.repository.IpoRepository;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.hibernate.Session;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class IpoSubscriptionService {

    private final IpoRepository ipoRepo;       // Spring Data JPA
    private final EntityManager entityManager;  // JPA standard API

    @Transactional
    public IpoResponse subscribe(IpoRequest request) {
        String id = "IPO-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        IpoSubscription sub = new IpoSubscription(id, request.accountId(), request.companyName(),
            request.lotSize(), request.lotsApplied(), request.pricePerShare());
        ipoRepo.save(sub);

        // JPA EntityManager — standard API (portable):
        log.info("EntityManager class: {}", entityManager.getClass().getSimpleName());
        // Output: SessionImpl (Hibernate's implementation of EntityManager)

        // Unwrap to Hibernate Session — for Hibernate-specific features:
        Session session = entityManager.unwrap(Session.class);
        log.info("Hibernate Session: {}", session.getClass().getSimpleName());
        // Use session for: Criteria API, NativeQuery, custom types, etc.

        log.info("IPO subscription {} created: Rs.{}", id, sub.getTotalAmount());
        return IpoResponse.from(sub);
    }

    @Transactional(readOnly = true)
    public List<IpoResponse> getByAccount(String accountId) {
        return ipoRepo.findByAccountIdAndStatus(accountId, "APPLIED").stream()
            .map(IpoResponse::from).toList();
    }
}
