package com.bank.ipo.service;

import com.bank.ipo.dto.*;
import com.bank.ipo.model.IpoSubscription;
import com.bank.ipo.repository.IpoRepository;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class IpoSubscriptionServiceTest {

    @Mock IpoRepository ipoRepo;
    @Mock EntityManager entityManager;
    @InjectMocks IpoSubscriptionService service;

    @Test
    void shouldCreateIpoSubscription() {
        when(ipoRepo.save(any(IpoSubscription.class))).thenAnswer(i -> i.getArgument(0));

        IpoResponse response = service.subscribe(
            new IpoRequest("SAV2001", "TechCorp", 15, 3, new BigDecimal("850")));

        assertThat(response.subscriptionId()).startsWith("IPO-");
        assertThat(response.totalAmount()).isEqualByComparingTo("38250"); // 850 × 15 × 3
        assertThat(response.status()).isEqualTo("APPLIED");
        verify(ipoRepo).save(any(IpoSubscription.class));
    }
}
